// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/environments", wrapper.ListEnvironments)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects", wrapper.ListProjects)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{projectId}", wrapper.GetProject)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/projects/{projectId}/quota", wrapper.GetProjectQuota)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalog/categories", wrapper.ListCatalogCategories)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalog/items", wrapper.ListCatalogItems)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalog/items/{itemId}", wrapper.GetCatalogItem)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/catalog/items/{itemId}/favourite", wrapper.RemoveFavourite)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/catalog/items/{itemId}/favourite", wrapper.AddFavourite)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/catalog/items/{itemId}/form", wrapper.GetRequestForm)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/forms/values", wrapper.ResolveFieldValues)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/requests/preview", wrapper.PreviewRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/requests", wrapper.ListRequests)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/requests", wrapper.CreateRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/requests/{requestId}", wrapper.GetRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/requests/{requestId}/steps", wrapper.ListRequestSteps)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/requests/{requestId}/steps/{stepId}/log", wrapper.GetStepLog)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/requests/{requestId}/cancel", wrapper.CancelRequest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/deployments", wrapper.ListDeployments)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/deployments/{deploymentId}", wrapper.GetDeployment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/events", wrapper.StreamEvents)

	return m
}

